/**
 * CommitmentIcons — the Sustainability page's commitment illustrations,
 * traced from the client-supplied glyph icons (public/images/sustainability/icons/*.png).
 *
 * Each icon renders three layers from the SAME source shapes:
 *   1. "template"  — the original compound paths, thin static grey guide.
 *   2. "draw"       — those same paths split one-segment-per-<path>
 *                     (GSAP's own DrawSVGPlugin guidance: browsers can't
 *                     reliably draw a single animated stroke through a
 *                     path with multiple "M" moveto commands), stroke-only.
 *   3. "fill"       — the ORIGINAL, unsplit compound paths again, solid
 *                     brand-accent fill. Splitting is only safe for the
 *                     stroke: a compound path's holes (e.g. the inside of
 *                     a glass, a letter counter) only render correctly
 *                     when its sub-paths stay together in one <path>, so
 *                     the final fill reuses the untouched originals.
 *
 * ImpactRow drives layer 2 with DrawSVGPlugin, then cross-fades layer 2
 * out and layer 3 in (opacity), never touching layer 1.
 */
import styles from './CommitmentIcons.module.css'

function Icon({ paths, ...props }) {
  const drawPaths = paths.flatMap(([d, transform]) =>
    d.match(/M[^M]*/g).map((seg) => [seg.trim(), transform])
  )
  return (
    <svg viewBox="0 0 512 512" {...props}>
      {paths.map(([d, transform], i) => (
        <path key={`t${i}`} className={styles.template} d={d} transform={transform || undefined} />
      ))}
      {drawPaths.map(([d, transform], i) => (
        <path key={`d${i}`} className={styles.draw} data-draw d={d} transform={transform || undefined} />
      ))}
      {paths.map(([d, transform], i) => (
        <path key={`f${i}`} className={styles.fill} data-fill d={d} transform={transform || undefined} />
      ))}
    </svg>
  )
}

